import math

def is_perfect_cube(n):
    if n == 0:
        return True
    # Calculate the nearest integer cube root
    root = round(n**(1/3))
    return root * root * root == n

results = {}
for x in range(-10, 11):
    # Calculate the expression E(x) = (8x - 41)(x + 3)^2
    term1 = 8 * x - 41
    term2 = x + 3
    expr_value = term1 * (term2 ** 2)

    if is_perfect_cube(expr_value):
        results[x] = expr_value

# Print results in a format suitable for logging
print("Found results:")
for x, value in results.items():
    print(f"x = {x}, Value = {value}")

def check_mod7(x):
    # N = (8x-41)(x+3)^2
    # Modulo 7:
    # 8x - 41 \equiv x - 6 \equiv x + 1 \pmod 7
    # x + 3 \pmod 7
    # N \equiv (x+1)(x+3)^2 \pmod 7
    x_mod_7 = x % 7
    term1 = (x_mod_7 + 1) % 7
    term2 = (x_mod_7 + 3) % 7
    n_mod_7 = (term1 * term2 * term2) % 7
    return n_mod_7

# Cubic residues mod 7 are {0, 1, 6}
cubic_residues = {0, 1, 6}

results = {}
for x in range(7):
    n_mod_7 = check_mod7(x)
    is_cube_residue = n_mod_7 in cubic_residues
    results[x] = {"N mod 7": n_mod_7, "Is Cube Residue": is_cube_residue}

print(results)

